## `ring_buffer.c`

```c
#include "ring_buffer.h"

/*
 * 割り込みセーフの核:
 *   1) データ書き込み完了
 *   2) __atomic_store_n(RELEASE) → メモリバリア（x86では implicit）
 *   3) 他側が __atomic_load_n(ACQUIRE) でインデックスを読み、
 *      その後データを読む
 *
 * これにより「半端に書かれたデータを読む」ことが原理的に防止される。
 */

void ring_buffer_init(ring_buffer_t *rb)
{
    __atomic_store_n(&rb->head, 0, __ATOMIC_RELEASE);
    __atomic_store_n(&rb->tail, 0, __ATOMIC_RELEASE);
    memset((void *)rb->buf, 0, RING_BUF_SIZE);
}

int ring_buffer_push(ring_buffer_t *rb, uint8_t data)
{
    /* 現在の tail を読み取り（消費者が更新する側） */
    size_t tail = __atomic_load_n(&rb->tail, __ATOMIC_ACQUIRE);
    size_t head = rb->head;          /* 生産者自身の値、volatile で十分 */

    /* 満杯チェック: head - tail == SIZE → 満杯 */
    if (head - tail >= RING_BUF_SIZE)
        return -1;

    /* --- データ書き込み（この時点では tail 側の視界には入らない） --- */
    rb->buf[head & RING_BUF_MASK] = data;

    /* --- RELEASE バリア: データ書き込みを完了してから head を公開 --- */
    __atomic_store_n(&rb->head, head + 1, __ATOMIC_RELEASE);

    return 0;
}

int ring_buffer_pop(ring_buffer_t *rb, uint8_t *data)
{
    /* 現在の head を読み取り（生産者が更新する側） */
    size_t head = __atomic_load_n(&rb->head, __ATOMIC_ACQUIRE);
    size_t tail = rb->tail;          /* 消費者自身の値、volatile で十分 */

    /* 空チェック */
    if (tail >= head)
        return -1;

    /* --- データ読み取り（head 更新は ACQUIRE により本読みより前に完了） --- */
    *data = rb->buf[tail & RING_BUF_MASK];

    /* --- RELEASE バリア: 読み取り完了後に tail を公開 --- */
    __atomic_store_n(&rb->tail, tail + 1, __ATOMIC_RELEASE);

    return 0;
}

size_t ring_buffer_count(const ring_buffer_t *rb)
{
    size_t head = __atomic_load_n((size_t *)&rb->head, __ATOMIC_ACQUIRE);
    size_t tail = __atomic_load_n((size_t *)&rb->tail, __ATOMIC_ACQUIRE);
    return head - tail;
}

int ring_buffer_is_empty(const ring_buffer_t *rb)
{
    return ring_buffer_count(rb) == 0;
}
