## `main.c`（使用例: ISR 生産者 + メインループ消費者）

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include "ring_buffer.h"

/*
 * 実機 ISR 例（Linux kernel 等）では ring_buffer_push を
 * 割り込みハンドラ内で呼ぶ。ここでは POSIX タイマーで模擬する。
 */

static ring_buffer_t rb;

/* --- 模擬 ISR（シグナルハンドラ）: 1バイトを push --- */
static volatile int isr_counter = 0;

static void isr_handler(int sig)
{
    (void)sig;
    uint8_t byte = (uint8_t)(isr_counter++ & 0xFF);
    if (ring_buffer_push(&rb, byte) != 0) {
        /* 満杯: 本来はハードウェアの FIFO でドロップ等 */
    }
}

int main(void)
{
    ring_buffer_init(&rb);

    /* POSIX タイマーで 10 ms ごとに SIGUSR1 → ISR 模擬 */
    struct sigaction sa = { .sa_handler = isr_handler };
    sigemptyset(&sa.sa_mask);
    sigaction(SIGUSR1, &sa, NULL);

    timer_t timerid;
    struct sigevent sev = { .sigev_notify = SIGEV_SIGNAL, .sigev_signo = SIGUSR1 };
    timer_create(CLOCK_REALTIME, &sev, &timerid);

    struct itimerspec its = {
        .it_interval  = { .tv_sec = 0, .tv_nsec = 10000000 }, /* 10 ms */
        .it_value     = { .tv_sec = 0, .tv_nsec = 10000000 },
    };
    timer_settime(timerid, 0, &its, NULL);

    printf("ISR(10ms) → ring buffer → main loop\n");
    printf("Ctrl+C to stop.\n\n");

    int total = 0;
    while (1) {
        uint8_t data;
        if (ring_buffer_pop(&rb, &data) == 0) {
            printf("[main] consumed: 0x%02X  (pending: %zu)\n",
                   data, ring_buffer_count(&rb));
            total++;
        }
        usleep(5000); /* 5 ms 間隔で消費 → 滞留が溜まる */
    }

    timer_delete(timerid);
    return 0;
}
```

